pattern.code_snippet:
start_date = 'YYYY-MM-DD'
end_date = 'YYYY-MM-DD'
lines = env['account.analytic.line'].search([
    ('date', '>=', start_date),
    ('date', '<=', end_date),
])
by_group = {}
for line in lines:
    grp = line.account_id.group_id
    gid = grp.id if grp else 0
    if gid not in by_group:
        by_group[gid] = {'group': grp.name if grp else 'Sin grupo', 'income': 0, 'expense': 0}
    if line.amount >= 0:
        by_group[gid]['income'] += line.amount
    else:
        by_group[gid]['expense'] += line.amount
result = []
for data in by_group.values():
    result.append({
        'group': data['group'],
        'income': data['income'],
        'expense': data['expense'],
        'balance': data['income'] + data['expense'],
    })
result = sorted(result, key=operator.itemgetter('balance'), reverse=True)
result
